    private readonly ImageLayerOperations _layers=new();private readonly ImageDocumentOperations _documents=new();private readonly ImageValueOperations _values=new();
    private ShaderMaterial? Material(Control workspace,Resource layer,bool content,bool capture)
    {
        var canvas=workspace.Get("canvas").As<Control>();var selection=canvas.Get("selection").As<Image>();if(selection==null)return null;var extent=content?_layers.content_dimensions(layer):layer.Get("dimensions").AsVector2();var corners=new Vector2[4];var world=_documents.world_transform(workspace.Get("document").As<Resource>(),layer);var bridge=GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_selection_fill.gd");var uvs=new[]{Vector2.Zero,Vector2.Right,Vector2.One,Vector2.Down};for(int index=0;index<uvs.Length;index++){var position=world*_layers.project_point(layer,uvs[index]*extent,new Vector2(-1,-1));var point=bridge.Call("_selection_point",canvas,position).AsVector2();corners[index]=point/(Vector2)selection.GetSize();}var rows=canvas.Call("_selection_projection",corners).AsGodotArray();if(rows.Count==0)return null;var a=rows[0].AsVector3();var b=rows[1].AsVector3();var c=rows[2].AsVector3();var inverse=new Basis(new Vector3(a.X,b.X,c.X),new Vector3(a.Y,b.Y,c.Y),new Vector3(a.Z,b.Z,c.Z)).Inverse();string code=capture?Code.Replace("COLOR=mix(texture(TEXTURE,UV),fill_color,coverage*fill_opacity);","COLOR=vec4(coverage);",StringComparison.Ordinal):Code;var material=new ShaderMaterial{Shader=new Shader{Code=code}};material.SetShaderParameter("row0",new Vector3(inverse.X.X,inverse.Y.X,inverse.Z.X));material.SetShaderParameter("row1",new Vector3(inverse.X.Y,inverse.Y.Y,inverse.Z.Y));material.SetShaderParameter("row2",new Vector3(inverse.X.Z,inverse.Y.Z,inverse.Z.Z));material.SetShaderParameter("mask_texture",ImageTexture.CreateFromImage(selection));var warp=layer.Get("warp").AsGodotObject();if(warp!=null&&warp.Get("enabled").AsBool()){material.SetShaderParameter("warped",true);material.SetShaderParameter("deformation",warp.Call("texture"));material.SetShaderParameter("field_size",(Vector2)warp.Get("grid_size").AsVector2I());}return material;
