    public Settings prepare_capture(Control workspace,Resource layer)
    {
        if(workspace.Get("canvas").AsGodotObject().Get("selection").AsGodotObject()==null)return new Settings();var material=Material(workspace,layer,true,true);if(material==null)return new Settings();var extent=_layers.content_dimensions(layer);extent*=(float)Math.Min(1,2048/Math.Max(1,Math.Max(extent.X,extent.Y)));var target=new SubViewport{Disable3D=true,TransparentBg=true,Size=((Vector2I)extent.Ceil()).Max(Vector2I.One),RenderTargetUpdateMode=SubViewport.UpdateMode.Always};workspace.AddChild(target);using var white=Image.CreateEmpty(1,1,false,Image.Format.Rgba8);white.Fill(Colors.White);target.AddChild(new TextureRect{Texture=ImageTexture.CreateFromImage(white),ExpandMode=TextureRect.ExpandModeEnum.IgnoreSize,Size=(Vector2)target.Size,Material=material});return new Settings{["target"]=target};
